int *divingBoard(int shorter, int longer, int k, int *returnSize) {
  if (k == 0) {
    *returnSize = 0;
    return NULL;
  }
  if (shorter == longer) {
    int *res = (int *)malloc(sizeof(int));
    res[0] = shorter * k;
    *returnSize = 1;
    return res;
  }
  int *res = (int *)malloc(sizeof(int) * (k + 1));
  for (int i = 0; i <= k; i++) {
    res[i] = shorter * (k - i) + longer * i;
  }
  *returnSize = k + 1;
  return res;
}

class Solution {
public:
  vector<int> divingBoard(int shorter, int longer, int k) {
    vector<int> res;
    if (k == 0) return res;
    if (shorter == longer) {
      res.push_back(shorter * k);
      return res;
    }
    for (int i = 0; i <= k; i++) {
      res.push_back(shorter * (k - i) + longer * i);
    }
    return res;
  }
};

func divingBoard(shorter int, longer int, k int) []int {
	res := []int{}
	if k == 0 {
		return res
	}
	if shorter == longer {
		return []int{shorter * k}
	}
	for i := 0; i <= k; i++ {
		res = append(res, shorter*(k-i)+longer*i)
	}
	return res
}

class Solution {
  public int[] divingBoard(int shorter, int longer, int k) {
    List<Integer> res = new ArrayList<>();
    if (k == 0) return new int[0];
    if (shorter == longer) {
      return new int[] { shorter * k };
    }
    for (int i = 0; i <= k; i++) {
      res.add(shorter * (k - i) + longer * i);
    }
    return res.stream().mapToInt(Integer::intValue).toArray();
  }
}

class Solution:
    def divingBoard(self, shorter: int, longer: int, k: int) -> List[int]:
        if k == 0:
            return []
        if shorter == longer:
            return [shorter * k]
        return [shorter * (k - i) + longer * i for i in range(k + 1)]

impl Solution {
  pub fn diving_board(shorter: i32, longer: i32, k: i32) -> Vec<i32> {
    if k == 0 {
      return vec![];
    }
    if shorter == longer {
      return vec![shorter * k];
    }
    (0..=k).map(|i| shorter * (k - i) + longer * i).collect()
  }
}

const divingBoard = (shorter: number, longer: number, k: number): number[] => {
  if (k === 0) return [];
  if (shorter === longer) return [shorter * k];
  const res: number[] = [];
  for (let i = 0; i <= k; i++) res.push(shorter * (k - i) + longer * i);
  return res;
};
